const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.seller_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_SELLER_ID', message: 'seller_id is required.' } }];
}
if (!body.request_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_REQUEST_ID', message: 'request_id is required.' } }];
}
// results is now optional. approval.jsx already has the real report the
// moment 32/34 respond, so it passes results directly - no reason to
// make it wait on an extra fetch. A dashboard row only ever has a
// request_id, so it omits results entirely; Resolve Results below reads
// the same real data from merge_requests.direct_submission_report
// instead - not a different source, just fetched here rather than
// handed over.
const results = Array.isArray(body.results) && body.results.length > 0 ? body.results : null;

return [{ json: {
  decision: 'VALID',
  seller_id: body.seller_id,
  request_id: body.request_id,
  results: results
}}];

const rows = $input.first().json;
const row = Array.isArray(rows) ? rows[0] : rows;
return [{ json: row || {} }];

// Same pattern as 27's Fetch Child Listings, proven there already - real
// attributes per SKU via the Listings API, so missing_data recommendations
// can cite actual sibling evidence instead of guessing. Keyed off results'
// own SKUs, using the same verified_parent/verified_child key each row
// already carries to tell parent from children - not a name guess, since
// there's no parent_sku field on this workflow's own input to rely on.
return (async function() {
  const ctx = $('Validate Input').first().json;
  const results = $('Resolve Results').first().json.results;
  const childSkus = results
    .filter(function(r) { return !Object.prototype.hasOwnProperty.call(r, 'verified_parent'); })
    .map(function(r) { return r.sku; });

  const accessToken = $('Exchange for Access Token').first().json.access_token;
  const sellingPartnerId = $('Get Seller Selling Partner ID').first().json.selling_partner_id;
  const marketplaceId = $('Fetch Merge Request').first().json.marketplace_id;

  const listings = [];
  for (const sku of childSkus) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId
          + '/' + encodeURIComponent(sku)
          + '?marketplaceIds=' + marketplaceId + '&includedData=summaries,attributes',
        headers: { 'x-amz-access-token': accessToken },
        json: true
      });
      listings.push({ sku: sku, attributes: (response && response.attributes) || {}, fetch_error: null });
    } catch (err) {
      listings.push({ sku: sku, attributes: {}, fetch_error: (err && err.message) || 'unknown error' });
    }
  }
  return listings.map(function(l) { return { json: l }; });
}).call(this);

// SAFETY, same principle wf20 already proved: the AI's own claimed status
// per row is never trusted as the source of truth. It gets overwritten
// here from the real results data directly - the AI can get the
// explanation wrong without that ever being able to misrepresent whether
// something actually succeeded.
const ctx = $('Validate Input').first().json;
const results = $('Resolve Results').first().json.results;
const raw = $input.first().json;
const text = (raw.content && raw.content[0] && raw.content[0].text) || '';
const cleaned = text.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{ json: {
    decision: 'EXPLANATION_UNAVAILABLE',
    request_id: ctx.request_id,
    message: 'Could not parse an explanation this time - the real submission result is unaffected.',
    raw_results: results
  }}];
}

function realStatus(row) {
  if (Object.prototype.hasOwnProperty.call(row, 'verified_parent')) {
    if (row.verified_parent === true) return 'verified';
  } else if (row.verified_child === true) {
    return 'verified';
  }
  const hasRealError = (row.patch_status === 'INVALID')
    || (Array.isArray(row.patch_issues) && row.patch_issues.length > 0)
    || (Array.isArray(row.verify_issues) && row.verify_issues.some(function(i) { return i.severity === 'ERROR'; }));
  return hasRealError ? 'failed' : 'pending';
}

const realStatusBySku = {};
results.forEach(function(row) { realStatusBySku[row.sku] = realStatus(row); });

const rowExplanations = Array.isArray(parsed.row_explanations) ? parsed.row_explanations : [];
const correctedRows = results.map(function(row) {
  const aiRow = rowExplanations.find(function(r) { return r.sku === row.sku; }) || {};
  return {
    sku: row.sku,
    status: realStatusBySku[row.sku],
    explanation: aiRow.explanation || null,
    recommendation: aiRow.recommendation || null
  };
});

// Surfaced so the frontend can call 35 to actually apply a fix without a
// separate lookup - Fetch Merge Request already has both of these on the
// row it fetched, just never passed them any further downstream before.
const mergeRow = $('Fetch Merge Request').first().json;

return [{ json: {
  decision: 'EXPLAINED',
  request_id: ctx.request_id,
  dimension1_attribute: mergeRow.dimension1_attribute || null,
  dimension2_attribute: mergeRow.dimension2_attribute || null,
  overall_summary: parsed.overall_summary || null,
  row_explanations: correctedRows,
  merge_recommendation: parsed.merge_recommendation || null
}}];

// If Validate Input already had results (approval.jsx's case), use them
// directly - no extra work needed. Otherwise (a dashboard row, which only
// ever has a request_id), fall back to direct_submission_report, the same
// real column Fetch Merge Request already pulled in full (no explicit
// select= on that node's URL, so PostgREST returns every column by
// default - this one included).
const ctx = $('Validate Input').first().json;
const mergeRequestRow = $json;

const results = ctx.results || mergeRequestRow.direct_submission_report;

return [{ json: {
  results: Array.isArray(results) ? results : null
}}];
